'use client'
import { useEffect, useRef } from 'react'
import * as THREE from 'three'

export default function GasPump3D() {
  const mountRef = useRef<HTMLDivElement>(null!)

  useEffect(() => {
    if (!mountRef.current) return

    // Scene setup
    const scene = new THREE.Scene()
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000)
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true })
    
    renderer.setSize(window.innerWidth, window.innerHeight)
    mountRef.current.appendChild(renderer.domElement)

    // Pump group
    const pumpGroup = new THREE.Group()

    // Chrome body - MeshStandardMaterial
    const bodyGeo = new THREE.CylinderGeometry(1.2, 1.2, 4, 32)
    const bodyMat = new THREE.MeshStandardMaterial({ 
      color: 0x333333, 
      metalness: 0.8, 
      roughness: 0.2 
    })
    const pumpBody = new THREE.Mesh(bodyGeo, bodyMat)
    pumpGroup.add(pumpBody)

    // Neon dial
    const dialGeo = new THREE.CylinderGeometry(0.9, 0.9, 0.2, 32)
    const dialMat = new THREE.MeshPhongMaterial({ 
      color: 0x00ff88, 
      transparent: true, 
      opacity: 0.4 
    })
    const dial = new THREE.Mesh(dialGeo, dialMat)
    dial.position.y = 0.8
    pumpGroup.add(dial)

    // Hose
    const hosePoints = [
      new THREE.Vector3(0, -1.5, 0),
      new THREE.Vector3(1.2, -2.2, 0),
      new THREE.Vector3(2, -1.2, 0)
    ]
    const hoseCurve = new THREE.CatmullRomCurve3(hosePoints)
    const hoseGeo = new THREE.TubeGeometry(hoseCurve, 64, 0.12, 16)
    const hoseMat = new THREE.MeshPhongMaterial({ 
      color: 0x444444, 
      emissive: 0x111111 
    })
    const hose = new THREE.Mesh(hoseGeo, hoseMat)
    pumpGroup.add(hose)

    // Neon sign
    const signGeo = new THREE.PlaneGeometry(2.2, 0.8)
    const signMat = new THREE.MeshBasicMaterial({ color: 0x00ff88 })
    const sign = new THREE.Mesh(signGeo, signMat)
    sign.position.set(0, 2.2, 1.1)
    pumpGroup.add(sign)

    scene.add(pumpGroup)
    camera.position.z = 5

    // Lighting
    scene.add(new THREE.AmbientLight(0x404040, 0.4))
    const neonLight = new THREE.PointLight(0x00ff88, 1.5, 100)
    neonLight.position.set(5, 5, 5)
    scene.add(neonLight)

    let time = 0
    const animate = () => {
      requestAnimationFrame(animate)
      time += 0.01
      pumpGroup.rotation.y = time * 0.3
      dial.rotation.z = time * 2
      renderer.render(scene, camera)
    }
    animate()

    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight
      camera.updateProjectionMatrix()
      renderer.setSize(window.innerWidth, window.innerHeight)
    }
    window.addEventListener('resize', handleResize)

    return () => {
      window.removeEventListener('resize', handleResize)
      if (mountRef.current && renderer.domElement) {
        mountRef.current.removeChild(renderer.domElement)
      }
      renderer.dispose()
    }
  }, [])

  return <div ref={mountRef} className="fixed inset-0 w-full h-full -z-10" />
}
